// Poppins, subset to Latin-1 plus the punctuation the CV uses, base64-encoded
// for jsPDF's virtual file system.
//
// The PDF base-14 faces (Helvetica, Times) are universally available but look
// like a 1990s form. Poppins is a geometric sans that matches the app's own
// display type, and subsetting keeps all three weights to ~55KB — small
// enough to embed in the lazily-loaded export chunk rather than shipping it
// with the app.
//
// Regenerate with fonttools:
//   pyftsubset Poppins-Regular.ttf --text=<latin-1 + punctuation> \
//     --layout-features= --no-hinting --drop-tables+=GSUB,GPOS,GDEF,DSIG,FFTM

export const POPPINS_REGULAR =
  '';

export const POPPINS_MEDIUM =
  '';

export const POPPINS_BOLD =
  '';

